e","value":"Fox Point Farms, Encinitas","note":"1200 Fox Point Farms Lane, Encinitas, CA 92024"},{"icon":"clock","label":"When","value":"Every Friday","note":"9am to 10:10am"}],"quote":"“True belonging is not passive. It’s not the belonging that comes with just joining a group.”","quoteBy":"Dr. Brené Brown","primaryLabel":"Get directions","primaryHref":"https://share.google/Pwn7yM4FAS1VedbL7","secondaryLabel":"","secondaryHref":"","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkSteps","props":{"id":"tg-fridays-first","eyebrow":"Your first Friday","title":"No agenda. No pressure. *No pitch.*","lead":"","steps":[{"title":"Show up at 9","body":"Fox Point Farms, Encinitas. Park, grab a coffee, and say hi to whoever''s closest.","ctaLabel":"","ctaHref":""},{"title":"Check in","body":"Scan the guest check-in at the gate so we can say hello by name next week.","ctaLabel":"","ctaHref":""},{"title":"Join the circle","body":"Shared stories, a featured speaker, and time to just listen. Done by 10:10.","ctaLabel":"Speak on a Friday","ctaHref":"https://www.thegroupcoastal.com/featuredspeaker-1"},{"title":"Meet June for coffee","body":"The one rule for every member, new and old. Book thirty minutes with June.","ctaLabel":"Book coffee","ctaHref":"https://calendly.com/june-thegroupcoastal/30min"}],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkFounder","props":{"id":"tg-fridays-hosts","eyebrow":"Feel Good Fridays with June An & Carol Yeh-Garner","quote":"Together, June and Carol create a welcoming, inspiring environment where people can connect, grow, and *rise.*","body":"June An is the founder of The Group, a fast-growing San Diego community built around connection, emotional intelligence, and authentic leadership. Carol Yeh-Garner is a wellness leader, clinical hypnotherapist, and top-ranked entrepreneur known for helping people transform their lives from the inside out.","image":"/brand/the-group/photos/core-team.jpg","alt":"June An and Carol Yeh-Garner","hosts":[{"image":"/brand/the-group/photos/team-june.jpg","name":"June An","role":"Founder"},{"image":"/brand/the-group/photos/team-carol.jpg","name":"Carol Yeh-Garner","role":"Core team · Fridays co-host"}],"ctaLabel":"Get coffee with June","ctaHref":"https://calendly.com/june-thegroupcoastal/30min","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkEvents","props":{"id":"tg-fridays-events","anchor":"events","eyebrow":"Events","title":"This week *and next.*","lead":"Chapter mornings, circles, workshops and parties across San Diego. RSVP to anything and add it to your calendar.","actionLabel":"Submit an event","actionHref":"https://www.thegroupcoastal.com/events-and-workshop-submission","max":8,"chapters":[{"label":"Encinitas","match":"encinitas|leucadia|fox point|solana beach|cardiff|la costa|escondido|swami"},{"label":"La Jolla","match":"parakeet|general atomics|la jolla|motivation monday"},{"label":"North Park","match":"maya moon|adams ave|north park|team up tuesday"},{"label":"Oceanside","match":"oceanside|ocean st|garfield"},{"label":"Veterans","match":"veteran"},{"label":"North County","match":"coaches club|house party|break free"}],"moreLabel":"See more events","moreHref":"/spaces/the-group/calendar","empty":"No groups meet this day. Try another chapter.","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkCoffee","props":{"id":"tg-coffee-contact","anchor":"contact","image":"/brand/the-group/photos/june-hug.jpg","alt":"June An hugging a member at a Friday gathering","signature":"Meet June for coffee.","title":"The Group''s *golden rule.*","body":"Every member, new and old, gets thirty minutes with June. Pick a time that works and he''ll meet you for coffee in Encinitas or on a call.","ctaLabel":"Get coffee with June","ctaHref":"https://calendly.com/june-thegroupcoastal/30min","reachTitle":"Get in touch!","reachBody":"Excited about connecting with us? Drop us a message and we''ll reach out in a jiffy.","email":"June@thegroupcoastal.com","phone":"858-997-5951","links":[{"icon":"camera","label":"Instagram @thegroupsd","href":"https://www.instagram.com/thegroupsd/"}],"messageLabel":"Send a message","messageHref":"/spaces/the-group/contact","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}}]},"chapters":{"root":{"props":{}},"content":[{"type":"NetworkChapters","props":{"id":"tg-chapters-band","anchor":"chapters","eyebrow":"Chapters","title":"Pockets of community *across San Diego.*","lead":"Our vision is to create spaces throughout San Diego where everyone feels they belong, where ideas become reality, and where community becomes the foundation for growth.","chips":[{"icon":"sun","name":"Encinitas","line":"Feel Good Friday · Fox Point Farms","when":"Fri · 9 AM","href":"/spaces/the-group/fridays","on":true},{"icon":"waves","name":"La Jolla","line":"Motivation Mondays · Parakeet Cafe","when":"Mon · 9 AM","href":"/spaces/the-group-la-jolla","on":false},{"icon":"building","name":"North Park","line":"Team Up Tuesday · Maya Moon","when":"Tue · 9 AM","href":"/spaces/the-group-north-park","on":false},{"icon":"sun","name":"Oceanside","line":"Thrive on Thursday","when":"Thu · 9 AM","href":"/spaces/the-group-oceanside","on":false},{"icon":"mountain","name":"North County","line":"Coaches Club · House Party","when":"Monthly","href":"/spaces/the-group-north-county","on":false},{"icon":"flag","name":"Veterans","line":"Veteran Community Conversation","when":"Wed · 11:30 AM","href":"/spaces/the-group-veterans","on":false}],"cards":[],"notes":[],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkSplit","props":{"id":"tg-chapters-lj","eyebrow":"La Jolla Chapter","title":"The Group is growing: *Motivation Mondays.*","body":"The Group is growing and we are excited to announce the launch of Motivation Monday at Parakeet Cafe at 9:00 am. This new chapter is more than just a gathering. It is a chance to expand our movement of empowerment, inspiration, and support into the heart of San Diego.\nWhether you cannot always make it to Feel Good Fridays in Encinitas or you are ready to double down on connection by joining both, Motivation Monday was created for you. It is a place where authentic conversations spark new opportunities, where encouragement turns into action, and where people come together to lift each other higher both personally and professionally.","image":"/brand/the-group/photos/june-harvest.jpg","alt":"June An with members in La Jolla","mediaSide":"left","facts":[{"icon":"pin","label":"Where","value":"Parakeet Cafe, Nautilus","note":"3535 General Atomics Ct, SD, CA 92121"},{"icon":"clock","label":"When","value":"Every Monday","note":"9am to 10:10am"}],"quote":"“The goal is to build up the community with inspiration and a sense of support. Make the group what you want for you.”","quoteBy":"June An","primaryLabel":"Visit the La Jolla chapter","primaryHref":"/spaces/the-group-la-jolla","secondaryLabel":"","secondaryHref":"","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkFounder","props":{"id":"tg-chapters-amie","eyebrow":"Motivation Monday host","quote":"Empowering high-achievers to break free from burnout and *reconnect with their authentic selves.*","body":"Amie Barsky is a trauma-informed coach specializing in Nervous System Regulation and Somatic Processing, helping professionals transform overwhelm into sustainable success. Her approach integrates neuroscience with holistic healing methods, drawing from her personal journey of overcoming people pleasing, perfectionism and trauma.","image":"","alt":"","hosts":[{"image":"","name":"Amie Barsky","role":"Host · Motivation Mondays"}],"ctaLabel":"","ctaHref":"","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkEvents","props":{"id":"tg-chapters-events","anchor":"events","eyebrow":"Events","title":"Every chapter, *every week.*","lead":"Chapter mornings, circles, workshops and parties across San Diego. RSVP to anything and add it to your calendar.","actionLabel":"Submit an event","actionHref":"https://www.thegroupcoastal.com/events-and-workshop-submission","max":10,"chapters":[{"label":"Encinitas","match":"encinitas|leucadia|fox point|solana beach|cardiff|la costa|escondido|swami"},{"label":"La Jolla","match":"parakeet|general atomics|la jolla|motivation monday"},{"label":"North Park","match":"maya moon|adams ave|north park|team up tuesday"},{"label":"Oceanside","match":"oceanside|ocean st|garfield"},{"label":"Veterans","match":"veteran"},{"label":"North County","match":"coaches club|house party|break free"}],"moreLabel":"See more events","moreHref":"/spaces/the-group/calendar","empty":"No groups meet this day. Try another chapter.","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkCircles","props":{"id":"tg-chapters-circles","eyebrow":"Circles","title":"Find the people *who get it.*","lead":"Member-led circles meet between Fridays: women''s groups, coaches, new moms, breathwork on the beach and dance.","actionLabel":"Start a circle","actionHref":"https://www.thegroupcoastal.com/events-and-workshop-submission","circles":[{"icon":"coffee","title":"Women''s Group Coffee Meetup ☕️","body":"Heart-led women''s group for meaningful conversation and aligned support.","when":"Wednesdays · 12:45 PM","where":"Pannikin Coffee & Tea · Free","match":"Women''s Group Coffee"},{"icon":"heart","title":"Woman Within Circle","body":"A gentle drop-in circle of connection, healing and sisterhood.","when":"Every other Saturday · 9 AM","where":"Encinitas · Free","match":"Woman Within Circle"},{"icon":"coffee","title":"Networking and Connection over Coffee","body":"Coffee and connections, with 10% off at Lofty Coffee.","when":"Thursdays · 12 PM","where":"97 N Coast Highway Encinitas · Free","match":"Connection over Coffee"},{"icon":"mic","title":"The Coaches Club","body":"Coaches and practitioners building, growing and scaling their businesses.","when":"Monthly · 9:30 AM","where":"Via Zoom · Free","match":"Coaches Club"},{"icon":"heart","title":"New Moms Meetup","body":"Meet other new moms and learn from pregnancy, birth and postpartum experts.","when":"Monthly, the 28th · 12 PM","where":"Solana Beach · Free","match":"New Moms"},{"icon":"wind","title":"Breathwork in the Park","body":"Breathwork, community and nature time at Presidio Park.","when":"Every other Sunday · 4 PM","where":"Presidio Park · Free","match":"Breathwork in the Park"},{"icon":"sun","title":"Swami’s Beach Gathering in the Grass","body":"A revived Sunday community gathering on the grass at Swami''s.","when":"Sundays · 2 PM","where":"1298 S Coast Hwy 101 Encinitas · Free","match":"Swami"},{"icon":"music","title":"Encinitas Sunday Dance Jam","body":"Journey through the Five Elements on the dance floor. Donation based.","when":"Every other Sunday · 11 AM","where":"535 Encinitas Blvd Suite 100 · Paid","match":"Dance Jam"},{"icon":"heart","title":"Oceanside Womens Group","body":"Biweekly women''s circle in Oceanside. Bring a pillow to sit on.","when":"Every other Thursday · 3 PM","where":"411 Garfield St · Free","match":"Oceanside Womens"},{"icon":"spark","title":"Vibe Check 🌀","body":"A monthly gathering for conscious leaders to connect and collaborate.","when":"Monthly, the 18th · 3 PM","where":"Encinitas private residence · Paid","match":"Vibe Check"},{"icon":"waves","title":"Breath & Sound by the Sea","body":"A weekly heart-expanding gathering on the beach in Oceanside.","when":"Fridays · 6:30 PM","where":"2300 Ocean St · Paid","match":"Breath & Sound"},{"icon":"video","title":"Videography Meet-Up @ ICON Industries","body":"Videographers, editors and motion creatives connect and collaborate.","when":"Wednesday · 6 PM","where":"925 S. Orange St. Escondido · Free","match":"Videography"}],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}}]},"membership":{"root":{"props":{}},"content":[{"type":"NetworkHero","props":{"id":"tg-membership-hero","eyebrow":"Membership","title":"Your journey *starts here.*","lead":"Share your journey, your passions, and your dreams. Let your soul shine through and connect with those around you. Embrace the power of community and support on this amazing adventure.","primaryLabel":"Become a member today","primaryHref":"/spaces/the-group/memberships","secondaryLabel":"Get coffee with June","secondaryHref":"https://calendly.com/june-thegroupcoastal/30min","image":"/brand/the-group/photos/rooftop-gathering.jpg","alt":"Members of The Group together on a rooftop","focus":"50% 50%","crop":"leaf","featureMatch":"","featureNote":"","featureCta":"","proof":"8,500+ members","proofNote":"Free to start, upgrade any time","faces":[{"image":"/brand/the-group/photos/team-june.jpg"},{"image":"/brand/the-group/photos/team-carol.jpg"},{"image":"/brand/the-group/photos/team-lisel.jpg"}],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkSplit","props":{"id":"tg-membership-cares","eyebrow":"Join The Group","title":"A community *that cares.*","body":"Welcome to The Group Coastal, where connection, collaboration, and community come first. We believe that success isn''t just about what you do, but who you do it with. By signing up for our Membership, you''re joining a heart-centered network of entrepreneurs, professionals, and changemakers who genuinely support each other in business and in life.\nAs a member, you''ll gain access to our events, including our uplifting Feel Good Fridays, where we come together to share ideas, find inspiration, and build meaningful relationships. This isn''t just another networking group, it''s a movement of people who believe in growing together and making a real impact.\nWe''re excited to welcome you in.","image":"/brand/the-group/photos/hall-selfie.jpg","alt":"Members celebrating together","mediaSide":"right","facts":[],"quote":"","quoteBy":"","primaryLabel":"","primaryHref":"","secondaryLabel":"","secondaryHref":"","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkTiers","props":{"id":"tg-membership-tiers","eyebrow":"Choose your membership","title":"Get more involved *in every chapter.*","lead":"Start free. Basic opens every chapter and includes Frequency Crew; Premium adds the members circle and Premium journeys.","tiers":[{"icon":"sprout","name":"Free","price":"$0","cadence":"","tagline":"Start meeting the community.","features":"Join The Group on Frequency\nRSVP to Feel Good Fridays and every open event\nEvery chapter''s calendar in one place\nJoin open circles between Fridays\nMember updates by email","ctaLabel":"Join free","ctaHref":"/spaces/the-group/memberships","badge":"","featured":false},{"icon":"users","name":"Basic","price":"$19.99","cadence":"/ mo","tagline":"Every chapter, and Crew included.","features":"Everything in Free\nOne membership that counts in all five chapters\nFrequency Crew included: host your own circles, events and journeys\nA monthly Boost for a circle or Space you love\nMember tickets to members-only events","ctaLabel":"Join Basic","ctaHref":"/spaces/the-group/memberships","badge":"Most members","featured":true},{"icon":"rocket","name":"Premium","price":"$29.99","cadence":"/ mo","tagline":"The deepest way in.","features":"Everything in Basic\nThe Premium members circle\nPremium journeys from The Group\nFirst access to signature events","ctaLabel":"Join Premium","ctaHref":"/spaces/the-group/memberships","badge":"","featured":false}],"footnote":"Any paid membership includes Frequency Crew. Change or cancel any time.","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"CardGrid","props":{"id":"tg-membership-frequency","role":"list","eyebrow":"On Frequency","title":"What membership opens up.","subtitle":"The Group runs on Frequency, so your membership travels with you: every chapter, every circle and every event in one place.","columns":2,"cards":[{"icon":"","title":"Every chapter","body":"One membership counts in La Jolla, North Park, Oceanside, North County and Veterans.\nEvery chapter''s mornings on one calendar."},{"icon":"","title":"Circles and events","body":"Join open circles between Fridays.\nRSVP to every gathering, and get member tickets to members-only events."},{"icon":"","title":"Frequency Crew","body":"Any paid membership includes Crew.\nHost your own circles, events and journeys, with a monthly Boost for a circle or Space you love."},{"icon":"","title":"Journeys","body":"Guided journeys from The Group, with Premium journeys for Premium members."}],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkCoffee","props":{"id":"tg-coffee-contact","anchor":"contact","image":"/brand/the-group/photos/june-hug.jpg","alt":"June An hugging a member at a Friday gathering","signature":"Meet June for coffee.","title":"The Group''s *golden rule.*","body":"Every member, new and old, gets thirty minutes with June. Pick a time that works and he''ll meet you for coffee in Encinitas or on a call.","ctaLabel":"Get coffee with June","ctaHref":"https://calendly.com/june-thegroupcoastal/30min","reachTitle":"Get in touch!","reachBody":"Excited about connecting with us? Drop us a message and we''ll reach out in a jiffy.","email":"June@thegroupcoastal.com","phone":"858-997-5951","links":[{"icon":"camera","label":"Instagram @thegroupsd","href":"https://www.instagram.com/thegroupsd/"}],"messageLabel":"Send a message","messageHref":"/spaces/the-group/contact","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}}]},"studio":{"root":{"props":{}},"content":[{"type":"NetworkHero","props":{"id":"tg-studio-hero","eyebrow":"Incubator Studios","title":"Your story deserves a studio *that takes it seriously.*","lead":"The Group SD Incubator Studios is San Diego''s podcast and content production space, built for creators, brands, and business owners who are ready to show up professionally.","primaryLabel":"Reserve your session","primaryHref":"/spaces/the-group/contact","secondaryLabel":"See the packages","secondaryHref":"#packages","image":"/brand/the-group/photos/patio-coffee.jpg","alt":"Members talking over coffee","focus":"50% 50%","crop":"soft","featureMatch":"","featureNote":"","featureCta":"","proof":"Heart of the Matter is shot here","proofNote":"Encinitas","faces":[],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkSplit","props":{"id":"tg-studio-about","eyebrow":"Studio offerings","title":"Everything you need, *under one roof.*","body":"Whether you bring your own team or want us to handle the tech, we have a setup that fits your show and your budget. Space rental, full recording, or complete production with editing and delivery, all under one roof in San Diego.\nThe Group Incubator Studios is proud to offer a full-service concierge style studio, complete with everything you need for podcasts, content creation, photoshoots, interviews, and more. Heart of the Matter™ Podcast is shot inside The Group Incubator Studio.","image":"/brand/the-group/photos/hero-group.jpg","alt":"Members of The Group together","mediaSide":"left","facts":[{"icon":"mic","label":"For","value":"Podcasts and content","note":"Photoshoots, interviews and more"},{"icon":"pin","label":"Where","value":"Encinitas","note":"On-site support every session"}],"quote":"","quoteBy":"","primaryLabel":"","primaryHref":"","secondaryLabel":"","secondaryHref":"","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkOfferings","props":{"id":"tg-studio-packages","anchor":"packages","eyebrow":"Packages","title":"Pick the setup *that fits your show.*","lead":"Reserve your session: tell us what you''re making and we''ll reply to confirm availability and answer any questions.","items":[{"title":"Space Rental","price":"$200","unit":"/ hour","body":"Just the space: your show, your team. Comfortable seating, high-speed wifi, conference table and flatscreen TV, basic lighting, ample power outlets and charging station, plus on-site support.","ctaLabel":"Reserve","ctaHref":"/spaces/the-group/contact","featured":false},{"title":"Recording Only","price":"$350","unit":"/ hour","body":"We handle the tech, you bring the story. Everything in Space Rental plus professional audio recording, multi-camera setup with basic studio lighting, audio mixing, plus on-site support.","ctaLabel":"Reserve","ctaHref":"/spaces/the-group/contact","featured":true},{"title":"Recording + Basic","price":"$500","unit":"/ episode","body":"The complete production, polished and ready. Everything in Recording plus basic video editing with branded intro and outros + logo, post-production audio mixing, post-ready exports for social and more, plus on-site support.","ctaLabel":"Reserve","ctaHref":"/spaces/the-group/contact","featured":false}],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkMedia","props":{"id":"tg-studio-podcast","eyebrow":"Heart of the Matter","title":"Made in *this studio.*","lead":"","actionLabel":"View all episodes","actionHref":"https://www.youtube.com/@heartofthematterpod","items":[{"title":"","videoId":"mGOSomOf9E4","href":"","image":""},{"title":"","videoId":"DmyPqNhNf_E","href":"","image":""},{"title":"","videoId":"Bwmo5Iu5Vk8","href":"","image":""},{"title":"","videoId":"KM42-GV9jYo","href":"","image":""},{"title":"","videoId":"lIAKWYsLrjk","href":"","image":""},{"title":"","videoId":"AsqNe6yEFA0","href":"","image":""}],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkCoffee","props":{"id":"tg-coffee-contact","anchor":"contact","image":"/brand/the-group/photos/june-hug.jpg","alt":"June An hugging a member at a Friday gathering","signature":"Meet June for coffee.","title":"The Group''s *golden rule.*","body":"Every member, new and old, gets thirty minutes with June. Pick a time that works and he''ll meet you for coffee in Encinitas or on a call.","ctaLabel":"Get coffee with June","ctaHref":"https://calendly.com/june-thegroupcoastal/30min","reachTitle":"Get in touch!","reachBody":"Excited about connecting with us? Drop us a message and we''ll reach out in a jiffy.","email":"June@thegroupcoastal.com","phone":"858-997-5951","links":[{"icon":"camera","label":"Instagram @thegroupsd","href":"https://www.instagram.com/thegroupsd/"}],"messageLabel":"Send a message","messageHref":"/spaces/the-group/contact","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}}]},"about":{"root":{"props":{}},"content":[{"type":"NetworkHero","props":{"id":"tg-about-hero","eyebrow":"About The Group","title":"Heart-Centered. Community. *Tribe.*","lead":"The Group was founded by June An, with a bold vision: to create a \"non-networking\" networking community, a space where personal connections come first.","primaryLabel":"Become a member","primaryHref":"/spaces/the-group/membership","secondaryLabel":"Get coffee with June","secondaryHref":"https://calendly.com/june-thegroupcoastal/30min","image":"/brand/the-group/photos/founder-june-an.jpg","alt":"June An, founder of The Group","focus":"50% 30%","crop":"arch","featureMatch":"","featureNote":"","featureCta":"","proof":"","proofNote":"","faces":[],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkFounder","props":{"id":"tg-about-june","eyebrow":"Meet June An","quote":"Let The Group inspire you to live your dreams *with purpose and confidence.*","body":"June An is the visionary founder of The Group, a community born from the triumphs and trials of his own entrepreneurial journey. As a seasoned entrepreneur, June understands the personal and professional challenges that can often feel overwhelming. His journey has taken him through moments of helplessness and hopelessness, which fueled his passion to create a space where others don’t have to navigate these challenges alone. Inspired by his experiences, June founded The Group with a clear mission: to empower individuals to overcome obstacles and pursue their dreams with renewed hope and determination.","image":"/brand/the-group/photos/june-harvest.jpg","alt":"June An","hosts":[{"image":"/brand/the-group/photos/team-june.jpg","name":"June An","role":"Founder"},{"image":"/brand/the-group/photos/team-carol.jpg","name":"Carol Yeh-Garner","role":"Core team · Fridays co-host"},{"image":"/brand/the-group/photos/team-lisel.jpg","name":"Dr. Lisel","role":"Core team · Heart of the Matter"}],"ctaLabel":"Get coffee with June","ctaHref":"https://calendly.com/june-thegroupcoastal/30min","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkSplit","props":{"id":"tg-about-story","eyebrow":"The commitment","title":"Building a stronger community through *connection and collaboration.*","body":"From its inception, The Group aimed to transcend traditional networking, focusing instead on fostering genuine relationships that would lead to collective growth and success. We believed that in prioritizing real, meaningful connections, we could build a community where professionals and business owners could truly flourish together.\nThe Group envisions a thriving ecosystem where businesses flourish not just through competition but through collaboration. We aim to be the cornerstone of a vibrant professional community, fostering an environment where each member’s growth and success contribute to the prosperity of all.","image":"/brand/the-group/photos/rooftop-gathering.jpg","alt":"Members of The Group on a rooftop","mediaSide":"right","facts":[],"quote":"","quoteBy":"","primaryLabel":"","primaryHref":"","secondaryLabel":"","secondaryHref":"","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkTeam","props":{"id":"tg-about-team","eyebrow":"Building real connections","title":"Together, *we are stronger.*","lead":"Our primary focus is on building authentic, lasting connections. Through regular events, collaborative projects, and community-building activities, we create opportunities for our members to forge strong relationships. These connections are the foundation upon which every member’s business can thrive, providing a robust support system and a source of inspiration.","note":"If you are a professional or business owner passionate about growth and collaboration, The Group is your ideal community.","image":"/brand/the-group/photos/core-team.jpg","alt":"June, Carol and Dr. Lisel together","pillars":[{"title":"Learning","body":"Workshops, seminars and peer-to-peer mentoring, so the community is always growing and evolving."},{"title":"Ideas","body":"A platform to share insights, brainstorm solutions and inspire each other. Every idea, big or small, can spark change."},{"title":"Support","body":"Encouragement, advice and resources, so no member has to face their challenges alone."}],"quote":"Together, we are stronger. Together, we are The Group.","quoteBy":"","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkCoffee","props":{"id":"tg-coffee-contact","anchor":"contact","image":"/brand/the-group/photos/june-hug.jpg","alt":"June An hugging a member at a Friday gathering","signature":"Meet June for coffee.","title":"The Group''s *golden rule.*","body":"Every member, new and old, gets thirty minutes with June. Pick a time that works and he''ll meet you for coffee in Encinitas or on a call.","ctaLabel":"Get coffee with June","ctaHref":"https://calendly.com/june-thegroupcoastal/30min","reachTitle":"Get in touch!","reachBody":"Excited about connecting with us? Drop us a message and we''ll reach out in a jiffy.","email":"June@thegroupcoastal.com","phone":"858-997-5951","links":[{"icon":"camera","label":"Instagram @thegroupsd","href":"https://www.instagram.com/thegroupsd/"}],"messageLabel":"Send a message","messageHref":"/spaces/the-group/contact","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}}]}},"siteHero":{"eyebrow":"Every Friday · 9 AM · Fox Point Farms, Encinitas","heading":"The non‑networking *networking* group.","tagline":"No pressure. No pitch. Just good energy, meaningful conversations, and a community where you can show up as yourself.","action":{"label":"Come this Friday","href":"/spaces/the-group/fridays"},"secondary":{"label":"Get coffee with June","href":"https://calendly.com/june-thegroupcoastal/30min"}},"siteFooter":{"columns":[{"title":"Locations","links":[{"label":"Encinitas","href":"/spaces/the-group/fridays"},{"label":"La Jolla","href":"/spaces/the-group-la-jolla"},{"label":"North Park","href":"/spaces/the-group-north-park"},{"label":"Oceanside","href":"/spaces/the-group-oceanside"},{"label":"North County","href":"/spaces/the-group-north-county"},{"label":"Veterans","href":"/spaces/the-group-veterans"}]},{"title":"Explore","links":[{"label":"Feel Good Fridays","href":"/spaces/the-group/fridays"},{"label":"Events calendar","href":"/spaces/the-group/calendar"},{"label":"Incubator Studios","href":"/spaces/the-group/studio"},{"label":"Creative Collective","href":"https://www.thegroupcoastal.com/creative-collective"},{"label":"Merch","href":"/spaces/the-group/shop"},{"label":"Members portal","href":"https://thegroupportal.com"}]},{"title":"Contact","links":[{"label":"June@thegroupcoastal.com","href":"/spaces/the-group/contact"},{"label":"858-997-5951","href":"/spaces/the-group/contact"},{"label":"Instagram","href":"https://www.instagram.com/thegroupsd/"},{"label":"Get coffee with June","href":"https://calendly.com/june-thegroupcoastal/30min"}]}],"blurb":"Together, we are stronger.","line":null,"note":null,"suffix":"Powered by Frequency"},"profileData":{"kind":"Community","about":"The Group SD is a San Diego community for entrepreneurs, professionals, creatives, and business owners seeking authentic connections, collaboration, growth, and meaningful relationships. Discover community events, Heart of the Matter, and our Incubator Studios in Encinitas.","email":"June@thegroupcoastal.com","phone":"858-997-5951","website":"https://www.thegroupcoastal.com","address":"1200 Fox Point Farms Ln, Encinitas, CA 92024","hours":"Feel Good Fridays · every Friday, 9:00–10:10 AM","socials":[{"platform":"instagram","url":"https://www.instagram.com/thegroupsd/"}],"offerings":[{"title":"Incubator Studios: Space Rental","blurb":"Just the space: your show, your team. Comfortable seating, high-speed wifi, conference table and flatscreen TV, basic lighting, ample power outlets and charging station, plus on-site support.","price":200,"currency":"usd","priceModel":"fixed","durationMinutes":60,"recurring":"once","visibility":"listed"},{"title":"Incubator Studios: Recording Only","blurb":"We handle the tech, you bring the story. Everything in Space Rental plus professional audio recording, multi-camera setup with basic studio lighting, audio mixing, plus on-site support.","price":350,"currency":"usd","priceModel":"fixed","durationMinutes":60,"recurring":"once","visibility":"listed"},{"title":"Incubator Studios: Recording + Basic","blurb":"The complete production, polished and ready. Everything in Recording plus basic video editing with branded intro and outros + logo, post-production audio mixing, post-ready exports for social and more, plus on-site support.","price":500,"currency":"usd","priceModel":"fixed","recurring":"once","visibility":"listed"}]},"profileLayout":{"rows":[{"id":"r0","columns":2,"cells":[["about"],["memberships"]],"ratio":"lead"},{"id":"r1","columns":1,"cells":[["features"]]},{"id":"r2","columns":1,"cells":[["zigzag"]],"mt":"lg"},{"id":"r3","columns":2,"cells":[["editorial"],["callout"]],"ratio":"lead"},{"id":"r4","columns":2,"cells":[["events"],["accentBeat"]],"ratio":"lead","mt":"lg"},{"id":"r5","columns":1,"cells":[["cardGrid"]],"mt":"lg"},{"id":"r6","columns":1,"cells":[["circles"]]},{"id":"r7","columns":2,"cells":[["quote"],["story"]],"ratio":"trail","mt":"lg"},{"id":"r8","columns":2,"cells":[["offerings"],["embed"]],"ratio":"trail","mt":"lg"},{"id":"r9","columns":2,"cells":[["contact"],["business"]],"mt":"lg"}],"content":{"about":{"eyebrow":"Every Friday · 9 AM · Fox Point Farms, Encinitas","title":"The non‑networking networking group.","body":"No pressure. No pitch. Just good energy, meaningful conversations, and a community where you can show up as yourself."},"memberships":{"eyebrow":"Membership","title":"Your journey starts here.","body":"A heart-centered network of entrepreneurs, professionals, and changemakers who genuinely support each other in business and in life.","ctaLabel":"See memberships","note":"Any paid membership includes Frequency Crew."},"features":{"source":"custom","layout":"stats","columns":"3","items":[{"icon":"users","title":"8,500+","text":"active members"},{"icon":"calendar","title":"300+","text":"weekly attendees"},{"icon":"eye","title":"100,000+","text":"monthly profile views"}]},"zigzag":{"eyebrow":"Feel Good Fridays","title":"Start your Friday with good people.","body":"After a full week of building, creating, and showing up for your goals, Friday morning is your chance to exhale. A weekly ritual where conversations flow easily, new friendships form naturally, and familiar faces remind you that you''re part of something bigger.\n\nWhere: Fox Point Farms, 1200 Fox Point Farms Ln, Encinitas.\n\nWhen: Every Friday, 9:00–10:10 AM.","image":"/brand/the-group/photos/courtyard-group.jpg","alt":"A Friday morning circle at Fox Point Farms","mediaSide":"left"},"accentBeat":{"eyebrow":"PitchFest 2026","title":"Bring your idea. Bring your people.","body":"Sign up to pitch in front of the community, then celebrate together at the 2nd annual Presentations & Party, Wednesday, October 21, 5:30–8 PM at C3 Bank Encinitas.","buttonLabel":"Sign up to pitch","buttonUrl":"https://www.thegroupcoastal.com/pitchfest2026"},"events":{"eyebrow":"Events","title":"Find a group. Or fill one.","view":"list"},"editorial":{"eyebrow":"Your first Friday","title":"No agenda. No pressure. No pitch.","body":"1. Show up at 9. Fox Point Farms, Encinitas. Park, grab a coffee, and say hi to whoever''s closest.\n\n2. Check in. Scan the guest check-in at the gate so we can say hello by name next week.\n\n3. Join the circle. Shared stories, a featured speaker, and time to just listen. Done by 10:10.\n\n4. Meet June for coffee. The one rule for every member, new and old. Book thirty minutes with June."},"cardGrid":{"eyebrow":"Chapters","title":"Pockets of community across San Diego.","columns":"3","shape":"top","cards":[{"title":"Encinitas","text":"Feel Good Friday · Fox Point Farms · Fri · 9 AM","link":"/spaces/the-group/fridays","button":{"label":"Visit Encinitas","href":"/spaces/the-group/fridays"}},{"title":"La Jolla","text":"Motivation Mondays · Parakeet Cafe · Mon · 9 AM","link":"/spaces/the-group-la-jolla","button":{"label":"Visit La Jolla","href":"/spaces/the-group-la-jolla"}},{"title":"North Park","text":"Team Up Tuesday · Maya Moon · Tue · 9 AM","link":"/spaces/the-group-north-park","button":{"label":"Visit North Park","href":"/spaces/the-group-north-park"}},{"title":"Oceanside","text":"Thrive on Thursday · Thu · 9 AM","link":"/spaces/the-group-oceanside","button":{"label":"Visit Oceanside","href":"/spaces/the-group-oceanside"}},{"title":"North County","text":"Coaches Club · House Party · Monthly","link":"/spaces/the-group-north-county","button":{"label":"Visit North County","href":"/spaces/the-group-north-county"}},{"title":"Veterans","text":"Veteran Community Conversation · Wed · 11:30 AM","link":"/spaces/the-group-veterans","button":{"label":"Visit Veterans","href":"/spaces/the-group-veterans"}}]},"circles":{"eyebrow":"Circles","title":"Find the people who get it.","columns":"3","items":["0829e076-d890-9b6e-2a02-30106ba833da","7cba1a17-6e17-e49d-40fd-baff6c606148","b940a1ff-113b-2ac9-9cb0-477e6688ac2a","35041404-8e11-cba5-ec2e-7ec0cd8c883d","63d910a3-8b5e-e05e-8c63-3bd478f4e3bf","0666dc46-4873-038e-1fa3-84676da3ccbb"]},"quote":{"text":"The goal is to build up the community with inspiration and a sense of support. Make the group what you want for you.","by":"June An, founder"},"story":{"eyebrow":"The core team","title":"June, Carol and Dr. Lisel.","body":"The three people who hold it together every week. June founded The Group, Carol brings her grounding presence as a wellness leader and clinical hypnotherapist, and Dr. Lisel co-hosts Heart of the Matter with June.\n\nAmie Barsky hosts Motivation Mondays in La Jolla."},"offerings":{"eyebrow":"Incubator Studios","title":"Your story deserves a studio that takes it seriously.","ctaLabel":"Reserve"},"embed":{"url":"https://www.youtube.com/watch?v=mGOSomOf9E4"},"callout":{"title":"The Group''s golden rule.","body":"Every member, new and old, gets thirty minutes with June. Pick a time that works and he''ll meet you for coffee in Encinitas or on a call.","buttonLabel":"Get coffee with June","buttonUrl":"https://calendly.com/june-thegroupcoastal/30min","image":"/brand/the-group/photos/june-hug.jpg","aspect":"horizontal"}}},"storefront":{"tabLabel":"Merch","published":true},"coverScrim":"none","logoBackdrop":"none","profilePublished":true}'::jsonb)
