values ('fa34a518-960f-c09c-4451-fc794d1fdfd3', 'the-group-veterans', 'The Group Veterans', 'business', 'active', (select entity_id from _tg), 'dawn', true, 'network', 'free', false, '{}'::jsonb, 'c1d40f58-318b-4c7b-a331-21788d632fc9', 'The Group Veterans', 'Veteran Community Conversation', 'Veteran Community is a collaborative community within The Group SD where veterans and those who support them come together to listen, learn, and take action. Through honest conversations, shared experiences, resources, mentorship, and meaningful connections, we are creating opportunities that help veterans thrive in every area of life. Together, we’re building stronger individuals, stronger families, and stronger communities, one conversation at a time.', 'America/Los_Angeles', '/brand/the-group/the-group-sd-logo.png', '/brand/the-group/photos/courtyard-group.jpg', 'db42cbea-3229-9813-e691-cb0e05272808', 'Oceanside', 'CA', 'US', '{"theme":"modern","siteStyle":{"theme":"network","synced":true,"spaceFonts":"modern"},"pages":[{"slug":"home","label":"Home"}],"pageDocs":{"home":{"root":{"props":{}},"content":[{"type":"NetworkHero","props":{"id":"tg-veterans-hero","eyebrow":"Veterans chapter · The Group","title":"Veteran Community *Conversation.*","lead":"Veteran Community is a collaborative community within The Group SD where veterans and those who support them come together to listen, learn, and take action. Through honest conversations, shared experiences, resources, mentorship, and meaningful connections, we are creating opportunities that help veterans thrive in every area of life. Together, we’re building stronger individuals, stronger families, and stronger communities, one conversation at a time.","primaryLabel":"See the calendar","primaryHref":"/spaces/the-group-veterans/calendar","secondaryLabel":"Get coffee with June","secondaryHref":"https://calendly.com/june-thegroupcoastal/30min","image":"/brand/the-group/photos/courtyard-group.jpg","alt":"The Group Veterans","focus":"50% 50%","crop":"leaf","featureMatch":"","featureNote":"","featureCta":"","proof":"Part of The Group","proofNote":"8,500+ members across San Diego","faces":[{"image":"/brand/the-group/photos/team-june.jpg"},{"image":"/brand/the-group/photos/team-carol.jpg"},{"image":"/brand/the-group/photos/team-lisel.jpg"}],"layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}},{"type":"NetworkSplit","props":{"id":"tg-veterans-meeting","eyebrow":"Veteran Community Conversation","title":"Come find *your people.*","body":"No pressure. No pitch. Just good energy, meaningful conversations, and a community where you can show up as yourself.","image":"","alt":"","mediaSide":"left","facts":[{"icon":"pin","label":"Where","value":"Municipal","note":"1722 S Coast Hwy, Oceanside, CA 92054"},{"icon":"clock","label":"When","value":"Wednesdays","note":"11:30 AM–1:00 PM"}],"quote":"","quoteBy":"","primaryLabel":"All chapters","primaryHref":"/spaces/the-group/chapters","secondaryLabel":"Membership","secondaryHref":"/spaces/the-group/membership","layout":{"spaceTop":"default","spaceBottom":"default","visibility":"all"}}}]}},"siteHero":{"eyebrow":"Veterans chapter · The Group","heading":"Veterans.","tagline":"Veteran Community is a collaborative community within The Group SD where veterans and those who support them come together to listen, learn, and take action. Through honest conversations, shared experiences, resources, mentorship, and meaningful connections, we are creating opportunities that help veterans thrive in every area of life. Together, we’re building stronger individuals, stronger families, and stronger communities, one conversation at a time.","action":{"label":"See the calendar","href":"/spaces/the-group-veterans/calendar"}},"siteFooter":{"columns":[{"title":"Locations","links":[{"label":"Encinitas","href":"/spaces/the-group/fridays"},{"label":"La Jolla","href":"/spaces/the-group-la-jolla"},{"label":"North Park","href":"/spaces/the-group-north-park"},{"label":"Oceanside","href":"/spaces/the-group-oceanside"},{"label":"North County","href":"/spaces/the-group-north-county"},{"label":"Veterans","href":"/spaces/the-group-veterans"}]},{"title":"Explore","links":[{"label":"Feel Good Fridays","href":"/spaces/the-group/fridays"},{"label":"Events calendar","href":"/spaces/the-group/calendar"},{"label":"Incubator Studios","href":"/spaces/the-group/studio"},{"label":"Creative Collective","href":"https://www.thegroupcoastal.com/creative-collective"},{"label":"Merch","href":"/spaces/the-group/shop"},{"label":"Members portal","href":"https://thegroupportal.com"}]},{"title":"Contact","links":[{"label":"June@thegroupcoastal.com","href":"/spaces/the-group/contact"},{"label":"858-997-5951","href":"/spaces/the-group/contact"},{"label":"Instagram","href":"https://www.instagram.com/thegroupsd/"},{"label":"Get coffee with June","href":"https://calendly.com/june-thegroupcoastal/30min"}]}],"blurb":"Together, we are stronger.","line":null,"note":null,"suffix":"Powered by Frequency"},"profileData":{"kind":"Community","about":"Veteran Community is a collaborative community within The Group SD where veterans and those who support them come together to listen, learn, and take action. Through honest conversations, shared experiences, resources, mentorship, and meaningful connections, we are creating opportunities that help veterans thrive in every area of life. Together, we’re building stronger individuals, stronger families, and stronger communities, one conversation at a time.","email":"June@thegroupcoastal.com","phone":"858-997-5951","address":"Municipal, 1722 S Coast Hwy, Oceanside, CA 92054","hours":"Veteran Community Conversation · Wednesdays, 11:30 AM–1:00 PM","socials":[{"platform":"instagram","url":"https://www.instagram.com/thegroupsd/"}]},"profilePublished":true}'::jsonb)
