-- 7. Events: 77 rows from The Group Portal export. Tenancy is the Collective (space_id) so its
--    calendar holds every chapter; a chapter's own meetings are hosted by its Space (host_space_id), so each
--    chapter's calendar shows its own. Recurring series are anchors with an RRULE plus the first 60 days of
--    occurrences (lib/event-recurrence.ts); the daily job rolls the window forward from here.
insert into events (slug, title, description, host_id, scope_id, scope_type, starts_at, ends_at, time_zone, location, visibility, status, published_at, join_mode, category, energy_tag, attendance_mode, source, space_id, host_space_id, recurrence_type, recurrence_rule, is_cancelled)
values ('tg-team-up-tuesday-at-maya-moon-2026-10-13', 'Team Up Tuesday at Maya Moon', 'Come join the Tuesday Normal Heights chapter at Maya Moon', 'c1d40f58-318b-4c7b-a331-21788d632fc9', (select region_id from _tg), 'public', timestamptz '2026-10-13 09:00+00', timestamptz '2026-10-13 10:10+00', 'America/Los_Angeles', '3349 Adams Ave., San Diego, CA 92116', 'public', 'published', now(), 'rsvp', 'gathering', 'social', 'in_person', 'manual', 'db42cbea-3229-9813-e691-cb0e05272808', '1d827c03-ef5b-c3a0-f5b1-178a38e3cb50', 'weekly', 'FREQ=WEEKLY;BYDAY=TU', false)
on conflict (slug) do update set title = excluded.title, description = excluded.description, host_id = excluded.host_id, scope_id = excluded.scope_id, starts_at = excluded.starts_at, ends_at = excluded.ends_at, time_zone = excluded.time_zone, location = excluded.location, visibility = excluded.visibility, status = excluded.status, published_at = coalesce(events.published_at, excluded.published_at), join_mode = excluded.join_mode, category = excluded.category, energy_tag = excluded.energy_tag, space_id = excluded.space_id, host_space_id = excluded.host_space_id, recurrence_type = excluded.recurrence_type, recurrence_rule = excluded.recurrence_rule;
insert into events (slug, parent_event_id, starts_at, ends_at, recurrence_type, recurrence_until, recurrence_rule, is_cancelled,
  title, description, host_id, scope_id, scope_type, location, visibility, status, published_at, price_cents, currency, capacity, venmo_handle, join_mode,
  category, energy_tag, time_zone, cover_image_path, gallery_image_paths, poster_path, theme, details, space_id, host_space_id, domain_id,
  attendance_mode, online_url, venue_name, street, city, region, country, postal_code, geog, hide_address, journey_id, source, is_demo,
  posted_by_profile_id, organizer_name, organizer_contact)
select a.slug || '-' || d.day, a.id, (d.day || ' 09:00+00')::timestamptz, (d.day || ' 10:10+00')::timestamptz, 'none', null, null, false,
  a.title, a.description, a.host_id, a.scope_id, a.scope_type, a.location, a.visibility, a.status, a.published_at, a.price_cents, a.currency, a.capacity, a.venmo_handle, a.join_mode,
  a.category, a.energy_tag, a.time_zone, a.cover_image_path, a.gallery_image_paths, a.poster_path, a.theme, a.details, a.space_id, a.host_space_id, a.domain_id,
  a.attendance_mode, a.online_url, a.venue_name, a.street, a.city, a.region, a.country, a.postal_code, a.geog, a.hide_address, a.journey_id, a.source, a.is_demo,
  a.posted_by_profile_id, a.organizer_name, a.organizer_contact
from events a cross join (values ('2026-10-20'), ('2026-10-27'), ('2026-11-03'), ('2026-11-10'), ('2026-11-17'), ('2026-11-24'), ('2026-12-01'), ('2026-12-08')) as d(day)
where a.slug = 'tg-team-up-tuesday-at-maya-moon-2026-10-13'
on conflict (slug) do nothing;
insert into events (slug, title, description, host_id, scope_id, scope_type, starts_at, ends_at, time_zone, location, visibility, status, published_at, join_mode, category, energy_tag, attendance_mode, source, space_id, host_space_id, recurrence_type, recurrence_rule, is_cancelled)
values ('tg-veteran-community-conversation-2026-10-14', 'Veteran Community Conversation', 'Veteran Community is a collaborative community within the The Group SD where veterans and those who support them come together to listen, learn, and take action. Through honest conversations, shared experiences, resources, mentorship, and meaningful connections, we are creating opportunities that help veterans thrive in every area of life. Together, we’re building stronger individuals, stronger families, and stronger communities, one conversation at a time.', 'c1d40f58-318b-4c7b-a331-21788d632fc9', (select region_id from _tg), 'public', timestamptz '2026-10-14 11:30+00', timestamptz '2026-10-14 13:00+00', 'America/Los_Angeles', 'Municipal, 1722 S Coast Hwy, Oceanside, CA 92054', 'public', 'published', now(), 'rsvp', 'gathering', 'social', 'in_person', 'manual', 'db42cbea-3229-9813-e691-cb0e05272808', 'fa34a518-960f-c09c-4451-fc794d1fdfd3', 'weekly', 'FREQ=WEEKLY;BYDAY=WE', false)
on conflict (slug) do update set title = excluded.title, description = excluded.description, host_id = excluded.host_id, scope_id = excluded.scope_id, starts_at = excluded.starts_at, ends_at = excluded.ends_at, time_zone = excluded.time_zone, location = excluded.location, visibility = excluded.visibility, status = excluded.status, published_at = coalesce(events.published_at, excluded.published_at), join_mode = excluded.join_mode, category = excluded.category, energy_tag = excluded.energy_tag, space_id = excluded.space_id, host_space_id = excluded.host_space_id, recurrence_type = excluded.recurrence_type, recurrence_rule = excluded.recurrence_rule;
insert into events (slug, parent_event_id, starts_at, ends_at, recurrence_type, recurrence_until, recurrence_rule, is_cancelled,
  title, description, host_id, scope_id, scope_type, location, visibility, status, published_at, price_cents, currency, capacity, venmo_handle, join_mode,
  category, energy_tag, time_zone, cover_image_path, gallery_image_paths, poster_path, theme, details, space_id, host_space_id, domain_id,
  attendance_mode, online_url, venue_name, street, city, region, country, postal_code, geog, hide_address, journey_id, source, is_demo,
  posted_by_profile_id, organizer_name, organizer_contact)
select a.slug || '-' || d.day, a.id, (d.day || ' 11:30+00')::timestamptz, (d.day || ' 13:00+00')::timestamptz, 'none', null, null, false,
