values ('tg-videography-meet-up-icon-industries-2026-10-28', 'Videography Meet-Up @ ICON Industries', 'Every Wednesday, videographers, editors, and motion creatives come together at Icon Industries to connect, collaborate, and grow. Whether you''re running a solo operation, building a studio, or freelancing between gigs, this is a space built for us, a place to strengthen the local video community and help each other move forward.

We''ll talk about where the industry is heading, swap resources for creative and professional development, and support one another with connections and referrals. Expect honest conversation about the craft and the business behind it, from gear and workflows to pricing and clients, bring your questions, your projects, and your openness to help.', 'c1d40f58-318b-4c7b-a331-21788d632fc9', (select region_id from _tg), 'public', timestamptz '2026-10-28 18:00+00', timestamptz '2026-10-28 20:30+00', 'America/Los_Angeles', '925 S. Orange St. Escondido, CA', 'public', 'published', now(), 'rsvp', 'social', 'social', 'in_person', 'manual', 'db42cbea-3229-9813-e691-cb0e05272808', 'db42cbea-3229-9813-e691-cb0e05272808', 'none', null, false)
