values ('tg-breath-sound-by-the-sea-2026-11-13', 'Breath & Sound by the Sea', 'We’d like to invite you to our weekly heart expanding gathering on the beach ❤️✨
👁️ We will start with grounding and intention setting
🧘🏽‍♂️We’ll move into a practice to balance the chakras
 🐉 We’ll slay any limiting beliefs & stuck emotions through breathwork
🪄Then fully regulate our nervous systems through meditation, sound, Craniosacral and energetic touch

Please bring yoga mat/ beach towel, blanket & layers, eye mask, and water.', 'c1d40f58-318b-4c7b-a331-21788d632fc9', (select region_id from _tg), 'public', timestamptz '2026-11-13 18:30+00', timestamptz '2026-11-13 19:30+00', 'America/Los_Angeles', '2300 ocean st', 'public', 'published', now(), 'rsvp', 'social', 'social', 'in_person', 'manual', 'db42cbea-3229-9813-e691-cb0e05272808', 'ffad975a-6187-dfe4-9def-4cc891dda8da', 'none', null, false)
