values ('tg-woman-within-circle-2026-12-12', 'Woman Within Circle', 'You’re warmly invited to join our Women Within Circle, tomorrow a confidential, supportive space where women gather to connect authentically, be witnessed, and support one another through life’s joys and challenges.
Inspired by the spirit of Women Within and the Mankind Project, this circle offers an opportunity for honest sharing, deep listening, and meaningful connection in a safe and respectful environment.
There are circles like this all over the world and also a growing community here locally, including co-ed circles in Oceanside.', 'c1d40f58-318b-4c7b-a331-21788d632fc9', (select region_id from _tg), 'public', timestamptz '2026-12-12 09:30+00', timestamptz '2026-12-12 17:00+00', 'America/Los_Angeles', '464 Requeza street, Encinitas', 'public', 'published', now(), 'rsvp', 'social', 'social', 'in_person', 'manual', 'db42cbea-3229-9813-e691-cb0e05272808', 'db42cbea-3229-9813-e691-cb0e05272808', 'none', null, false)
